# ---------------------------------------------------------
# 1. 离散求导模块 (保持不变)
# ---------------------------------------------------------
class SimulinkDiscreteDerivative:
    def __init__(self, Ts=0.05, K=1.0, IC=0.0):
        self.Ts = Ts
        self.K = K
        self.state = IC 
    def update(self, u):
        current_weighted_input = (self.K * u) / self.Ts
        y = current_weighted_input - self.state
        self.state = current_weighted_input
        return y

