        self.gain_motor = 1.10
        self.num_cars = 6
        self.car_length = 20.0
        self.g = 9.8
        self.dt = 0.05                      
        
        # 滤波参数
        wc = 0.2 * 2 * np.pi
        denom = (2.0 / self.dt) + wc
        self.filt_b0 = wc / denom                   
        self.filt_b1 = self.filt_b0                  
        self.filt_a1 = (wc - (2.0 / self.dt)) / denom 
        self.eps = sys.float_info.epsilon   

        # 静态数据 (保留原本的大数组)
        self.load_real_gradient_data()
        self.load_real_curve_data()

