    def _interp_gradient(self, pos):
        return np.interp(pos, self.real_grad_locs, self.real_grad_vals)

    def _interp_curve(self, pos):
        return np.interp(pos, self.real_curve_locs, self.real_curve_vals)

    # === 核心物理计算逻辑 (严格复刻) ===
    
    def _calc_gradient_distributed(self, current_dist, loads):
        # 分布式坡度阻力
        F_G_total = 0.0
        steps = 20
        step_len = self.car_length / float(steps)
        for i in range(steps):
            term_sum = 0.0
            for car_idx in range(self.num_cars):
                Mk = loads[car_idx]
                car_head_pos = current_dist - car_idx * self.car_length
                slice_pos = car_head_pos - (i + 0.5) * step_len
                grad = self._interp_gradient(slice_pos)
                theta = math.atan(grad / 1000.0)
                term_sum += (Mk * math.sin(theta)) / float(steps)
            F_G_total += term_sum * self.g
        return F_G_total * 1000.0 

    def _calc_curve_distributed(self, current_dist, loads):
        # 分布式曲线阻力
        F_C_total = 0.0
        steps = 20
        step_len = self.car_length / float(steps)
        for car_idx in range(self.num_cars):
            Mk = loads[car_idx]
            car_fr_sum = 0.0
            for a in range(steps):
                car_head_pos = current_dist - car_idx * self.car_length
                slice_pos = car_head_pos - (a + 0.5) * step_len
                R = self._interp_curve(slice_pos)
                if 0 < R < 2000:
                    f_slice = (600.0 * self.g * Mk) / R / 1000.0 / float(steps)
                    car_fr_sum += f_slice
            F_C_total += car_fr_sum
        return F_C_total * 1000.0

    # === 外部接口：批处理 ===
    def run_batch_simulation(self, time_seq, vel_seq, mass_total_ton):
        """
        输入: 
            time_seq (s): 时间序列
            vel_seq (m/s): 速度序列
            mass_total_ton (t): 整车总质量 (我们的数据里只有这个)
        输出:
            energy_wh_seq: 每一步的能耗 (Wh)
        """
        # 1. 初始化状态
        self.derivative_module = SimulinkDiscreteDerivative(Ts=self.dt, K=1.0, IC=0.0)
        self.last_raw_acc = 0.0
        self.last_filt_acc = 0.0
        self.current_dist = 0.0 # 假设从0开始，或者根据数据校准
        self.total_theoretical_energy_kwh = 0.0
        
        # 2. 将总质量均分给6节车 (这是唯一的适配点)
        # 必须这样做才能跑得通 _calc_gradient_distributed
        single_car_mass = mass_total_ton / 6.0
        loads = np.array([single_car_mass] * 6)
        
        mass_ends = loads[0] + loads[5]
        mass_mids = np.sum(loads[1:5])
        mass_total = np.sum(loads)
        
        energy_results_wh = []
        
        # 3. 逐点仿真
        for i in range(len(time_seq)):
            v_ms = vel_seq[i]
            target_v_kmh = v_ms * 3.6
            
            # A. 严格求导 + 滤波
            raw_acc = self.derivative_module.update(v_ms)
            current_filtered_acc = (self.filt_b0 * raw_acc + 
                                    self.filt_b1 * self.last_raw_acc - 
                                    self.filt_a1 * self.last_filt_acc)
            self.last_raw_acc = raw_acc
            self.last_filt_acc = current_filtered_acc
            
            # B. 积分更新位置
            self.current_dist += v_ms * self.dt
            
            # C. 启动阻力逻辑 (MATLAB复刻)
            F_start_N = 0.0
            if v_ms > self.eps and v_ms < 0.05:
                F_start_N = (mass_total * 49.0 / 1000.0) * 1000.0
            
            # D. Davis 阻力
            t_mids = mass_mids * (self.P_b * abs(target_v_kmh) + self.P_a)
            t_ends = mass_ends * (self.P_d * abs(target_v_kmh) + self.P_c)
            t_aero = (self.P_f * 5.0 + self.P_e) * (target_v_kmh ** 2)
            F_davis = (t_mids + t_ends + t_aero) * 9.8
            F_basic_sum = F_davis + F_start_N
            
            # E. 附加阻力 (分布式)
            F_grad = self._calc_gradient_distributed(self.current_dist, loads) if v_ms > 0 else 0.0
            F_curve = self._calc_curve_distributed(self.current_dist, loads) if v_ms > 0 else 0.0
            
            # F. 惯性力 (Effective Mass)
            eff_mass = (mass_ends * self.gain_trailer + mass_mids * self.gain_motor) * 1000.0
            F_inertia = eff_mass * current_filtered_acc
            
            # G. 合力
            F_total_raw = F_inertia + (F_basic_sum + F_grad + F_curve)
            F_saturated = max(0.0, F_total_raw)
            
            # H. 功率与能耗
            # 机械功率 kW
            P_kw = (F_saturated * v_ms) / 1000.0
            
            # 你的C代码里没乘效率，这里保持一致，或者根据需要乘 0.9
            # 假设我们算的是机械能耗，之后 AI 负责学效率损失
            
            # 这一步的 Wh
            E_step_wh = (P_kw * self.dt / 3600.0) * 1000.0
            
            energy_results_wh.append(E_step_wh)
            
        return np.array(energy_results_wh)